#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <iostream>
using namespace fedspatial;
static bool load(const std::string&n,Matrix*x){return read_matrix("sync_gpu/tests/fixtures/sync_gpu/"+n,x);}
int main(){Matrix k(2,2),s(3,2),z(3,1),x(3,1),g(1,1),mu(2,1),sig(2,2);double a[]={0,0,1,.2,.3,1.1},b[]={0,0,1.5,1.5},c[]={1.2,-.4,.7};std::copy(a,a+6,s.a.begin());std::copy(b,b+4,k.a.begin());std::copy(c,c+3,z.a.begin());for(double&v:x.a)v=1;g(0,0)=.15;mu(0,0)=.2;mu(1,0)=-.1;sig(0,0)=.7;sig(1,1)=.4;sig(0,1)=sig(1,0)=.05;GpuContext ctx(0);double worst=0,worst_rel=0;for(int i=0;i<7;i++){Matrix p,r;if(!load("DELTA_THETA_POINT"+std::to_string(i)+"_PARAM.txt",&p)||!load("DELTA_THETA_POINT"+std::to_string(i)+"_GRAD.txt",&r))return 2;auto q=compute_delta_theta_local(ctx,{s,z,x},k,{g,mu,sig,p(0,0),p(1,0),p(2,0)});double ed=std::abs(q.gradient[0]-r(0,0)),ea=std::abs(q.gradient[1]-r(1,0)),er=std::abs(q.gradient[2]-r(2,0));worst=std::max({worst,ed,ea,er});for(int j=0;j<3;++j)worst_rel=std::max(worst_rel,std::abs(q.gradient[j]-r(j,0))/std::max(1e-300,std::abs(r(j,0))));std::cout<<"POINT"<<i<<"_GRAD_DELTA_ERROR="<<ed<<"\nPOINT"<<i<<"_GRAD_ALPHA_ERROR="<<ea<<"\nPOINT"<<i<<"_GRAD_RANGE_ERROR="<<er<<"\n";}std::cout<<"DELTA_THETA_GRAD_MAX_ABS_ERROR="<<worst<<"\nDELTA_THETA_GRAD_MAX_REL_ERROR="<<worst_rel<<"\nDELTA_THETA_GRAD_PARITY="<<(worst<=1e-8?"PASS":"FAIL")<<"\n";return worst<=1e-8?0:1;}
